-- Additive migration. Uses sports_ai_ prefixes because SQLite has no named schemas.
CREATE TABLE IF NOT EXISTS sports_ai_fixtures(id TEXT PRIMARY KEY, external_id TEXT NOT NULL, source TEXT NOT NULL, sport TEXT NOT NULL, competition TEXT NOT NULL, home TEXT NOT NULL, away TEXT NOT NULL, starts_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', statistics_json TEXT NOT NULL, odds_json TEXT NOT NULL, observed_at TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS sports_ai_analysis_runs(id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, fixture_count INTEGER NOT NULL DEFAULT 0, selection_count INTEGER NOT NULL DEFAULT 0, ticket_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sports_ai_predictions(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES sports_ai_analysis_runs(id), fixture_id TEXT NOT NULL REFERENCES sports_ai_fixtures(id), sport TEXT NOT NULL, fixture TEXT NOT NULL, market TEXT NOT NULL, odds REAL NOT NULL, probability REAL NOT NULL, edge REAL NOT NULL, model_name TEXT NOT NULL, UNIQUE(run_id,fixture_id,market));
CREATE TABLE IF NOT EXISTS sports_ai_tickets(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES sports_ai_analysis_runs(id), tier INTEGER NOT NULL, combined_odds REAL NOT NULL, estimated_probability REAL NOT NULL, estimated_ev REAL NOT NULL, selection_count INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'candidate');
CREATE TABLE IF NOT EXISTS sports_ai_ticket_legs(id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES sports_ai_tickets(id), fixture_id TEXT NOT NULL REFERENCES sports_ai_fixtures(id), market TEXT NOT NULL, decimal_odds REAL NOT NULL, estimated_probability REAL NOT NULL, UNIQUE(ticket_id,fixture_id));
CREATE TABLE IF NOT EXISTS sports_ai_booking_codes(id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL UNIQUE REFERENCES sports_ai_tickets(id), code TEXT NOT NULL, verification_method TEXT NOT NULL, evidence TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'unverified', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sports_ai_notifications(id TEXT PRIMARY KEY, channel TEXT NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sports_ai_audit_events(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sports_ai_fixtures_sport_date ON sports_ai_fixtures(sport,starts_at);
CREATE INDEX IF NOT EXISTS sports_ai_predictions_run_edge ON sports_ai_predictions(run_id,edge);
CREATE INDEX IF NOT EXISTS sports_ai_tickets_tier ON sports_ai_tickets(tier);
